package com.karambwanticker;

import java.awt.Color;

final class Colors
{
	private Colors()
	{
	}

	static Color withAlpha(Color color, int alpha)
	{
		return new Color(color.getRed(), color.getGreen(), color.getBlue(), Math.max(0, Math.min(255, alpha)));
	}

	/** A faded version of the color, for the target that isn't your next click. */
	static Color faded(Color color)
	{
		return withAlpha(color, color.getAlpha() / 3);
	}
}

package com.karambwanticker;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ProgressPieComponent;

/**
 * Optional small tick timer that follows the mouse, so the cue is where you're already looking.
 */
class CursorOverlay extends Overlay
{
	private static final int DIAMETER = 12;
	private static final int OFFSET = 18;

	private final Client client;
	private final KarambwanTickerPlugin plugin;
	private final KarambwanTickerConfig config;

	@Inject
	CursorOverlay(Client client, KarambwanTickerPlugin plugin, KarambwanTickerConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showCursorTimer() || !plugin.isActive())
		{
			return null;
		}

		Point mouse = client.getMouseCanvasPosition();
		if (mouse == null || mouse.getX() < 0)
		{
			return null;
		}

		Color color = plugin.getStateColor();
		ProgressPieComponent pie = new ProgressPieComponent();
		pie.setPosition(new Point(mouse.getX() + OFFSET, mouse.getY() + OFFSET));
		pie.setDiameter(DIAMETER);
		pie.setProgress(plugin.getTickRemaining());
		pie.setFill(Colors.withAlpha(color, 190));
		pie.setBorderColor(color);
		pie.render(graphics);
		return null;
	}
}

package com.karambwanticker;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import javax.inject.Inject;
import net.runelite.api.Point;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.ui.overlay.WidgetItemOverlay;
import net.runelite.client.ui.overlay.components.ProgressPieComponent;

/**
 * Highlights the next raw karambwan with the tick timer and dims cooked/burnt ones.
 */
class InventoryOverlay extends WidgetItemOverlay
{
	private static final BasicStroke STROKE = new BasicStroke(2);
	private static final Color DIM = new Color(0, 0, 0, 150);
	private static final int SLOT_PIE_DIAMETER = 12;

	private final KarambwanTickerPlugin plugin;
	private final KarambwanTickerConfig config;

	@Inject
	InventoryOverlay(KarambwanTickerPlugin plugin, KarambwanTickerConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		showOnInventory();
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		if (!plugin.isActive())
		{
			return;
		}

		Rectangle bounds = widgetItem.getCanvasBounds();
		boolean isTargetSlot = widgetItem.getWidget().getIndex() == plugin.getNextSlot();

		if (config.dimCooked()
			&& !(isTargetSlot && plugin.isFixedSlot())
			&& (itemId == ItemID.TBWT_COOKED_KARAMBWAN
				|| itemId == ItemID.TBWT_BURNT_KARAMBWAN
				|| itemId == ItemID.TBWT_POORLY_COOKED_KARAMBWAN))
		{
			graphics.setColor(DIM);
			graphics.fill(bounds);
			return;
		}

		if (!config.showInventoryIndicator() || !isTargetSlot)
		{
			return;
		}

		// Following modes only mark raw karambwans; the fixed slot is marked whatever it holds.
		if (!plugin.isFixedSlot() && itemId != KarambwanTickerPlugin.RAW_KARAMBWAN)
		{
			return;
		}

		Color color = plugin.getStateColor();
		if (config.emphasizeNextStep()
			&& plugin.getTickState() != KarambwanTickerPlugin.TickState.DONE
			&& plugin.isRangeNextStep())
		{
			// Karambwan is already selected; your next click is the fire.
			color = Colors.faded(color);
		}

		KarambwanTickerConfig.IndicatorStyle style = config.indicatorStyle();

		if (style != KarambwanTickerConfig.IndicatorStyle.PIE)
		{
			graphics.setColor(Colors.withAlpha(color, 45));
			graphics.fill(bounds);
			graphics.setStroke(STROKE);
			graphics.setColor(color);
			graphics.draw(bounds);
		}

		if (style != KarambwanTickerConfig.IndicatorStyle.OUTLINE)
		{
			ProgressPieComponent pie = new ProgressPieComponent();
			pie.setPosition(new Point(
				(int) bounds.getMaxX() - SLOT_PIE_DIAMETER / 2,
				(int) bounds.getMinY() + SLOT_PIE_DIAMETER / 2));
			pie.setDiameter(SLOT_PIE_DIAMETER);
			pie.setProgress(plugin.getTickRemaining());
			pie.setFill(Colors.withAlpha(color, 170));
			pie.setBorderColor(color);
			pie.render(graphics);
		}
	}
}

package com.karambwanticker;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(KarambwanTickerConfig.GROUP)
public interface KarambwanTickerConfig extends Config
{
	String GROUP = "karambwanticker";

	enum IndicatorStyle
	{
		OUTLINE,
		PIE,
		BOTH
	}

	enum SlotOrder
	{
		/** Follows the first raw karambwan, moving down as they cook. */
		TOP_DOWN("Top Down"),
		/** Always the bottom-right inventory slot, so the target never moves. */
		BOTTOM_RIGHT("Bottom Right");

		private final String displayName;

		SlotOrder(String displayName)
		{
			this.displayName = displayName;
		}

		@Override
		public String toString()
		{
			return displayName;
		}
	}

	@ConfigSection(
		name = "Indicators",
		description = "Where and how the tick timer is drawn",
		position = 0
	)
	String indicatorSection = "indicators";

	@ConfigSection(
		name = "Colors",
		description = "Colors for each part of the tick",
		position = 1
	)
	String colorSection = "colors";

	@ConfigSection(
		name = "Stats",
		description = "Missed-tick and XP tracking",
		position = 2
	)
	String statsSection = "stats";

	// ---------------- Indicators ----------------

	@ConfigItem(
		keyName = "showRangeIndicator",
		name = "Fire/range indicator",
		description = "Show the tick timer on the fire or range you're cooking on",
		section = indicatorSection,
		position = 0
	)
	default boolean showRangeIndicator()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showInventoryIndicator",
		name = "Next karambwan indicator",
		description = "Highlight the next raw karambwan to click with the tick timer",
		section = indicatorSection,
		position = 1
	)
	default boolean showInventoryIndicator()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showCursorTimer",
		name = "Timer by cursor",
		description = "Also draw a small tick timer next to your mouse cursor",
		section = indicatorSection,
		position = 2
	)
	default boolean showCursorTimer()
	{
		return false;
	}

	@ConfigItem(
		keyName = "indicatorStyle",
		name = "Style",
		description = "Outline the target, draw a countdown pie on it, or both",
		section = indicatorSection,
		position = 3
	)
	default IndicatorStyle indicatorStyle()
	{
		return IndicatorStyle.BOTH;
	}

	@ConfigItem(
		keyName = "emphasizeNextStep",
		name = "Emphasize next click",
		description = "Fade whichever target isn't your next click (fire once a karambwan is selected, karambwan otherwise)",
		section = indicatorSection,
		position = 4
	)
	default boolean emphasizeNextStep()
	{
		return true;
	}

	@ConfigItem(
		keyName = "slotOrder",
		name = "Highlight order",
		description = "Top Down follows the next raw karambwan; Bottom Right stays fixed on the bottom-right inventory slot",
		section = indicatorSection,
		position = 5
	)
	default SlotOrder slotOrder()
	{
		return SlotOrder.TOP_DOWN;
	}

	@ConfigItem(
		keyName = "dimCooked",
		name = "Dim cooked karambwans",
		description = "Darken cooked and burnt karambwans so they don't catch your eye or your click",
		section = indicatorSection,
		position = 6
	)
	default boolean dimCooked()
	{
		return true;
	}

	@Range(min = 10, max = 40)
	@ConfigItem(
		keyName = "pieSize",
		name = "Pie size",
		description = "Diameter of the countdown pie on the fire/range",
		section = indicatorSection,
		position = 7
	)
	default int pieSize()
	{
		return 22;
	}

	// ---------------- Colors ----------------

	@Alpha
	@ConfigItem(
		keyName = "readyColor",
		name = "Click now",
		description = "Tick is open and you haven't cooked yet this tick",
		section = colorSection,
		position = 0
	)
	default Color readyColor()
	{
		return new Color(0, 255, 0, 220);
	}

	@Alpha
	@ConfigItem(
		keyName = "hurryColor",
		name = "Hurry",
		description = "Tick is about to end and you haven't cooked yet",
		section = colorSection,
		position = 1
	)
	default Color hurryColor()
	{
		return new Color(255, 140, 0, 230);
	}

	@Alpha
	@ConfigItem(
		keyName = "doneColor",
		name = "Done this tick",
		description = "You've already clicked the fire this tick; get the next karambwan ready",
		section = colorSection,
		position = 2
	)
	default Color doneColor()
	{
		return new Color(0, 170, 255, 200);
	}

	@Range(min = 50, max = 500)
	@Units(Units.MILLISECONDS)
	@ConfigItem(
		keyName = "hurryMs",
		name = "Hurry window",
		description = "How long before the tick ends the indicator switches to the Hurry color",
		section = colorSection,
		position = 3
	)
	default int hurryMs()
	{
		return 200;
	}

	// ---------------- Stats ----------------

	@ConfigItem(
		keyName = "showStats",
		name = "Stats panel",
		description = "Show cooks, missed ticks, efficiency and XP/hr while ticking",
		section = statsSection,
		position = 0
	)
	default boolean showStats()
	{
		return true;
	}

	@Range(min = 2, max = 20)
	@ConfigItem(
		keyName = "idleResetTicks",
		name = "Break after (ticks)",
		description = "Ticks without a cook before the plugin treats it as a break (banking) instead of missed ticks",
		section = statsSection,
		position = 1
	)
	default int idleResetTicks()
	{
		return 5;
	}
}

package com.karambwanticker;

import com.google.inject.Provides;
import java.awt.Color;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.MenuAction;
import net.runelite.api.Player;
import net.runelite.api.Scene;
import net.runelite.api.Skill;
import net.runelite.api.Tile;
import net.runelite.api.WorldView;
import net.runelite.api.events.GameObjectDespawned;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.StatChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;

/**
 * Visual aid for 1-tick karambwan cooking.
 *
 * Draws a tick countdown on the fire/range and the next raw karambwan, changing color when
 * the tick is open, about to close, or already used. It also tracks missed ticks.
 *
 * This plugin only draws overlays and reads game state. It never sends input, clicks, or
 * changes menu entries.
 */
@PluginDescriptor(
	name = "Karambwan Ticker",
	description = "Tick timer on your fire/range and next raw karambwan for 1-tick karambwan cooking",
	tags = {"cooking", "karambwan", "tick", "1t", "timer", "metronome", "skilling"}
)
public class KarambwanTickerPlugin extends Plugin
{
	static final int RAW_KARAMBWAN = ItemID.TBWT_RAW_KARAMBWAN;
	private static final int COOKED_KARAMBWAN = ItemID.TBWT_COOKED_KARAMBWAN;
	private static final int BURNT_KARAMBWAN = ItemID.TBWT_BURNT_KARAMBWAN;
	private static final int POORLY_COOKED_KARAMBWAN = ItemID.TBWT_POORLY_COOKED_KARAMBWAN;

	private static final long TICK_NANOS = 600_000_000L;
	private static final int BOTTOM_RIGHT_SLOT = 27;
	private static final int MAX_TARGET_DISTANCE = 12;
	private static final String RAW_KARAMBWAN_NAME = "raw karambwan";
	private static final String RAW_KARAMBWAN_TARGET_PREFIX = RAW_KARAMBWAN_NAME + " ->";

	enum TickState
	{
		READY,
		HURRY,
		DONE
	}

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private KarambwanTickerConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private RangeOverlay rangeOverlay;

	@Inject
	private InventoryOverlay inventoryOverlay;

	@Inject
	private CursorOverlay cursorOverlay;

	@Inject
	private StatsOverlay statsOverlay;

	/** The fire or range last used with a raw karambwan. */
	private GameObject target;

	private int nextSlot = -1;

	private int rawCount;

	private int productCount;

	// Tick timing
	private long lastTickNanos;
	private boolean clickedThisTick;
	private boolean karambwanSelectedByClick;
	private int tickCount;

	// Stats
	private boolean streakActive;
	private int lastCookTick = Integer.MIN_VALUE / 2;
	private int invCooks;
	private int invMissed;
	private int sessionCooks;
	private int sessionMissed;
	private long sessionXp;
	private int activeTicks;
	private int lastCookingXp = -1;

	// ------------------------------------------------------------------
	// Getters
	// ------------------------------------------------------------------

	GameObject getTarget()
	{
		return target;
	}

	int getNextSlot()
	{
		return nextSlot;
	}

	boolean isStreakActive()
	{
		return streakActive;
	}

	int getInvCooks()
	{
		return invCooks;
	}

	int getInvMissed()
	{
		return invMissed;
	}

	int getSessionCooks()
	{
		return sessionCooks;
	}

	int getSessionMissed()
	{
		return sessionMissed;
	}

	long getSessionXp()
	{
		return sessionXp;
	}

	int getActiveTicks()
	{
		return activeTicks;
	}

	@Provides
	KarambwanTickerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(KarambwanTickerConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(rangeOverlay);
		overlayManager.add(inventoryOverlay);
		overlayManager.add(cursorOverlay);
		overlayManager.add(statsOverlay);

		lastTickNanos = System.nanoTime();
		resetStats();

		clientThread.invoke(() ->
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				ItemContainer inv = client.getItemContainer(InventoryID.INV);
				if (inv != null)
				{
					updateInventory(inv, false);
				}
				lastCookingXp = client.getSkillExperience(Skill.COOKING);
			}
		});
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(rangeOverlay);
		overlayManager.remove(inventoryOverlay);
		overlayManager.remove(cursorOverlay);
		overlayManager.remove(statsOverlay);
		target = null;
		nextSlot = -1;
		rawCount = 0;
		productCount = 0;
	}

	void resetStats()
	{
		streakActive = false;
		lastCookTick = Integer.MIN_VALUE / 2;
		invCooks = 0;
		invMissed = 0;
		sessionCooks = 0;
		sessionMissed = 0;
		sessionXp = 0;
		activeTicks = 0;
	}

	// ------------------------------------------------------------------
	// Events
	// ------------------------------------------------------------------

	@Subscribe
	public void onGameTick(GameTick event)
	{
		tickCount++;
		lastTickNanos = System.nanoTime();
		clickedThisTick = false;

		if (streakActive && tickCount - lastCookTick > config.idleResetTicks())
		{
			streakActive = false;
		}

		// Forget the fire/range once we've walked away from it.
		Player player = client.getLocalPlayer();
		if (target != null && player != null
			&& player.getWorldLocation().distanceTo(target.getWorldLocation()) > MAX_TARGET_DISTANCE)
		{
			target = null;
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		String menuTarget = Text.removeTags(event.getMenuTarget()).toLowerCase();

		if (event.getMenuAction() == MenuAction.WIDGET_TARGET)
		{
			// "Use" on an inventory item: remember whether it was a raw karambwan.
			karambwanSelectedByClick = menuTarget.equals(RAW_KARAMBWAN_NAME);
			return;
		}

		boolean wasKarambwanSelected = isKarambwanSelected();
		karambwanSelectedByClick = false;

		if (event.getMenuAction() != MenuAction.WIDGET_TARGET_ON_GAME_OBJECT)
		{
			return;
		}

		if (!wasKarambwanSelected && !menuTarget.startsWith(RAW_KARAMBWAN_TARGET_PREFIX))
		{
			return;
		}

		clickedThisTick = true;

		GameObject clicked = findGameObject(event.getId(), event.getParam0(), event.getParam1());
		if (clicked != null)
		{
			target = clicked;
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.INV)
		{
			updateInventory(event.getItemContainer(), true);
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (event.getSkill() != Skill.COOKING)
		{
			return;
		}

		int xp = event.getXp();
		if (lastCookingXp >= 0 && xp > lastCookingXp && target != null)
		{
			sessionXp += xp - lastCookingXp;
		}
		lastCookingXp = xp;
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!KarambwanTickerConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}

		clientThread.invoke(() ->
		{
			ItemContainer inv = client.getItemContainer(InventoryID.INV);
			if (inv != null)
			{
				updateInventory(inv, false);
			}
		});
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		if (event.getGameObject() == target)
		{
			// Fire burned out or range unloaded.
			target = null;
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOADING || state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
		{
			// Scene object references are no longer valid after a reload.
			target = null;
		}
	}

	// ------------------------------------------------------------------
	// Inventory & cook detection
	// ------------------------------------------------------------------

	private void updateInventory(ItemContainer container, boolean detectCooks)
	{
		Item[] items = container.getItems();
		int raw = 0;
		int products = 0;
		int firstRaw = -1;

		for (int i = 0; i < items.length; i++)
		{
			int id = items[i].getId();
			if (id == RAW_KARAMBWAN)
			{
				raw++;
				if (firstRaw < 0)
				{
					firstRaw = i;
				}
			}
			else if (id == COOKED_KARAMBWAN || id == BURNT_KARAMBWAN || id == POORLY_COOKED_KARAMBWAN)
			{
				products++;
			}
		}

		// Exactly one raw turned into one cooked/burnt karambwan: that's a cook.
		if (detectCooks && raw == rawCount - 1 && products == productCount + 1)
		{
			onCook();
		}

		// A fresh inventory of raw karambwans was withdrawn.
		if (rawCount == 0 && raw > 0)
		{
			invCooks = 0;
			invMissed = 0;
		}

		rawCount = raw;
		productCount = products;
		nextSlot = config.slotOrder() == KarambwanTickerConfig.SlotOrder.BOTTOM_RIGHT ? BOTTOM_RIGHT_SLOT : firstRaw;
	}

	/** True when the indicator stays on the bottom-right slot no matter what's in it. */
	boolean isFixedSlot()
	{
		return config.slotOrder() == KarambwanTickerConfig.SlotOrder.BOTTOM_RIGHT;
	}

	private void onCook()
	{
		int gap = tickCount - lastCookTick;
		if (streakActive && gap >= 1 && gap <= config.idleResetTicks())
		{
			int missed = gap - 1;
			invMissed += missed;
			sessionMissed += missed;
			activeTicks += gap;
		}
		else
		{
			// First cook after a break.
			activeTicks += 1;
		}

		streakActive = true;
		lastCookTick = tickCount;
		invCooks++;
		sessionCooks++;
	}

	// ------------------------------------------------------------------
	// Helpers used by overlays
	// ------------------------------------------------------------------

	/** True when there's a known fire/range and raw karambwans left to cook. */
	boolean isActive()
	{
		return target != null && rawCount > 0;
	}

	boolean isKarambwanSelected()
	{
		if (!client.isWidgetSelected())
		{
			karambwanSelectedByClick = false;
			return false;
		}
		if (karambwanSelectedByClick)
		{
			return true;
		}
		Widget selected = client.getSelectedWidget();
		return selected != null && selected.getItemId() == RAW_KARAMBWAN;
	}

	/** Fraction of the current tick still remaining, from 1 (tick just started) to 0. */
	double getTickRemaining()
	{
		double elapsed = (System.nanoTime() - lastTickNanos) / (double) TICK_NANOS;
		return Math.max(0, Math.min(1, 1 - elapsed));
	}

	TickState getTickState()
	{
		if (clickedThisTick)
		{
			return TickState.DONE;
		}
		long remainingNanos = TICK_NANOS - (System.nanoTime() - lastTickNanos);
		if (remainingNanos < config.hurryMs() * 1_000_000L)
		{
			return TickState.HURRY;
		}
		return TickState.READY;
	}

	Color getStateColor()
	{
		switch (getTickState())
		{
			case DONE:
				return config.doneColor();
			case HURRY:
				return config.hurryColor();
			default:
				return config.readyColor();
		}
	}

	/** Whether the fire/range is the next thing to click, i.e. a raw karambwan is selected. */
	boolean isRangeNextStep()
	{
		return isKarambwanSelected();
	}

	private GameObject findGameObject(int id, int sceneX, int sceneY)
	{
		WorldView worldView = client.getTopLevelWorldView();
		if (worldView == null)
		{
			return null;
		}
		Scene scene = worldView.getScene();
		Tile[][][] tiles = scene.getTiles();
		int plane = worldView.getPlane();

		if (sceneX < 0 || sceneY < 0 || sceneX >= tiles[plane].length || sceneY >= tiles[plane][sceneX].length)
		{
			return null;
		}

		Tile tile = tiles[plane][sceneX][sceneY];
		if (tile == null)
		{
			return null;
		}

		for (GameObject object : tile.getGameObjects())
		{
			if (object != null && object.getId() == id)
			{
				return object;
			}
		}
		return null;
	}
}

package com.karambwanticker;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Shape;
import javax.inject.Inject;
import net.runelite.api.GameObject;
import net.runelite.api.Point;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.ui.overlay.components.ProgressPieComponent;

/**
 * Draws the tick timer on the fire/range. The pie sits at the bottom edge of the object's
 * clickbox so it stays visible when the inventory panel covers the top of the fire.
 */
class RangeOverlay extends Overlay
{
	private static final BasicStroke STROKE = new BasicStroke(2);

	private final KarambwanTickerPlugin plugin;
	private final KarambwanTickerConfig config;

	@Inject
	RangeOverlay(KarambwanTickerPlugin plugin, KarambwanTickerConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showRangeIndicator() || !plugin.isActive())
		{
			return null;
		}

		GameObject target = plugin.getTarget();
		Color color = plugin.getStateColor();
		if (config.emphasizeNextStep()
			&& plugin.getTickState() != KarambwanTickerPlugin.TickState.DONE
			&& !plugin.isRangeNextStep())
		{
			color = Colors.faded(color);
		}

		KarambwanTickerConfig.IndicatorStyle style = config.indicatorStyle();
		Shape clickbox = target.getClickbox();

		if (style != KarambwanTickerConfig.IndicatorStyle.PIE && clickbox != null)
		{
			OverlayUtil.renderPolygon(graphics, clickbox, color, Colors.withAlpha(color, 40), STROKE);
		}

		if (style != KarambwanTickerConfig.IndicatorStyle.OUTLINE)
		{
			Point piePos;
			if (clickbox != null)
			{
				Rectangle bounds = clickbox.getBounds();
				piePos = new Point((int) bounds.getCenterX(), (int) bounds.getMaxY() - config.pieSize() / 2);
			}
			else
			{
				piePos = target.getCanvasLocation();
			}

			if (piePos != null)
			{
				ProgressPieComponent pie = new ProgressPieComponent();
				pie.setPosition(piePos);
				pie.setDiameter(config.pieSize());
				pie.setProgress(plugin.getTickRemaining());
				pie.setFill(Colors.withAlpha(color, 170));
				pie.setBorderColor(color);
				pie.render(graphics);
			}
		}

		return null;
	}
}

package com.karambwanticker;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.MenuAction;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;
import net.runelite.client.util.QuantityFormatter;

/**
 * Cooks, missed ticks, efficiency and XP/hr while ticking. Right-click the panel to reset.
 */
class StatsOverlay extends OverlayPanel
{
	// 100 ticks per minute, 6000 per hour.
	private static final double TICKS_PER_HOUR = 6000.0;

	private final KarambwanTickerPlugin plugin;
	private final KarambwanTickerConfig config;

	@Inject
	StatsOverlay(KarambwanTickerPlugin plugin, KarambwanTickerConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		addMenuEntry(MenuAction.RUNELITE_OVERLAY, "Reset", "Karambwan Ticker", e -> plugin.resetStats());
		addMenuEntry(MenuAction.RUNELITE_OVERLAY_CONFIG, OverlayManager.OPTION_CONFIGURE, "Karambwan Ticker");
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showStats() || plugin.getTarget() == null)
		{
			return null;
		}

		panelComponent.getChildren().add(TitleComponent.builder()
			.text("Karambwan Ticker")
			.color(plugin.isStreakActive() ? Color.GREEN : Color.WHITE)
			.build());

		panelComponent.getChildren().add(LineComponent.builder()
			.left("This inv:")
			.right(plugin.getInvCooks() + " cooked, " + plugin.getInvMissed() + " missed")
			.build());

		int sessionCooks = plugin.getSessionCooks();
		int sessionMissed = plugin.getSessionMissed();
		int total = sessionCooks + sessionMissed;
		double efficiency = total == 0 ? 0 : 100.0 * sessionCooks / total;
		panelComponent.getChildren().add(LineComponent.builder()
			.left("Tick efficiency:")
			.right(total == 0 ? "-" : String.format("%.1f%%", efficiency))
			.rightColor(efficiency >= 90 ? Color.GREEN : efficiency >= 75 ? Color.YELLOW : Color.ORANGE)
			.build());

		int activeTicks = plugin.getActiveTicks();
		String xpHr = activeTicks < 20
			? "-"
			: QuantityFormatter.quantityToStackSize((long) (plugin.getSessionXp() * TICKS_PER_HOUR / activeTicks));
		panelComponent.getChildren().add(LineComponent.builder()
			.left("XP/hr (ticking):")
			.right(xpHr)
			.build());

		return super.render(graphics);
	}
}

